<?php
declare(strict_types=1);

function nzlegal_page(string $page): string {
    if($page==='privacy')return'<main class="page page-narrow"><div class="surface"><h1>حریم خصوصی نیازستان</h1><p class="lead">اطلاعات فقط برای ارائه سرویس، امنیت و مقابله با سوءاستفاده پردازش می‌شود.</p><div class="description"><b>اطلاعات حساب:</b> شماره موبایل تأییدشده، نام نمایشی و زمان فعالیت.<br><br><b>اطلاعات امنیتی:</b> آخرین IP شناخته‌شده، نوع دستگاه/مرورگر و User-Agent برای تشخیص سوءاستفاده، پشتیبانی و رسیدگی به گزارش‌ها نگهداری می‌شود و برای کاربران دیگر نمایش داده نمی‌شود. اطلاعات فنی کاربران غیرفعال در نگهداری دوره‌ای پاک یا حداقل می‌شود.<br><br><b>آگهی و گفتگو:</b> محتوای آگهی، رسانه، گفتگوها، گزارش‌ها و نتایج پایش امنیتی برای اداره پلتفرم ذخیره می‌شوند. پیام‌ها و تصاویر مشکوک ممکن است برای بررسی مدیر علامت‌گذاری شوند.<br><br><b>موقعیت:</b> موقعیت حدودی برای حفظ حریم خصوصی توصیه می‌شود. موقعیت دقیق فقط مطابق انتخاب کاربر در آگهی ذخیره می‌شود.<br><br><b>پرداخت:</b> اطلاعات کارت بانکی در نیازستان ذخیره نمی‌شود.<br><br><b>اشتراک‌گذاری:</b> شماره تماس، IP و اطلاعات دستگاه به سایر کاربران فروخته یا نمایش داده نمی‌شود؛ دسترسی مدیریتی صرفاً برای امنیت و پشتیبانی است.</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:18px"><a class="btn ghost" href="/nz?page=account-data">دریافت اطلاعات من</a><a class="btn ghost" href="/nz?page=account-delete">حذف حساب</a><a class="btn ghost" href="/nz?page=profile">بازگشت</a></div></div></main>';
    if($page==='rules')return'<main class="page page-narrow"><div class="surface"><h1>قوانین انتشار آگهی</h1><div class="description">ثبت اولیه آگهی رایگان است و انتشار پس از بررسی مدیر انجام می‌شود. آگهی تکراری یا بسیار مشابه، حتی با شماره، حساب یا شهر متفاوت، قابل ثبت نیست. محتوای مستهجن، برهنگی، توهین، تهدید، دشنام، کالای ممنوع، اطلاعات گمراه‌کننده و تصاویر مشکوک می‌تواند باعث توقف انتشار و بررسی فوری شود. آگهی منتشرشده ۳۰ روز فعال است و در صورت عدم تمدید از نمایش عمومی خارج می‌شود. ویرایش عنوان، توضیحات یا قیمت باعث بررسی دوباره آگهی می‌شود. کاربران مسئول صحت اطلاعات و رعایت قوانین معامله هستند و نیازستان می‌تواند برای امنیت، حساب یا گفتگوهای پرریسک را محدود کند.</div><a class="btn ghost" style="margin-top:18px" href="/nz">بازگشت</a></div></main>';
    if($page==='safety')return'<main class="page page-narrow"><div class="surface"><h1>راهنمای معامله امن</h1><div class="description">کد ورود پیامکی را برای هیچ‌کس ارسال نکنید. نیازستان برای دریافت پول، رمز کارت یا رمز پویا درخواست نمی‌کند. قبل از مشاهده و بررسی کالا بیعانه پرداخت نکنید. برای کالاهای گران‌قیمت معامله حضوری در محل امن انجام دهید. از لینک‌های پرداخت ناشناس، فایل‌های مشکوک و انتقال گفتگو به کانال‌های ناشناس خودداری کنید. در صورت مشاهده رفتار مشکوک، آگهی یا گفتگو را گزارش و کاربر را مسدود کنید.</div><a class="btn ghost" style="margin-top:18px" href="/nz">بازگشت</a></div></main>';
    if($page==='about')return'<main class="page page-narrow"><div class="surface"><h1>درباره نیازستان</h1><div class="description">نیازستان پلتفرم آگهی خرید، فروش و خدمات است که با تمرکز بر جستجوی محلی، ثبت کنترل‌شده آگهی، چت، گزارش تخلف و بررسی مدیریتی توسعه داده شده است.</div><a class="btn ghost" style="margin-top:18px" href="/nz">بازگشت</a></div></main>';
    if($page==='account-data')return'<main class="page page-narrow"><div class="surface"><h1>دریافت اطلاعات من</h1><p class="lead">نسخه‌ای از اطلاعات حساب، آگهی‌ها و داده‌های مرتبط با حساب شما به صورت JSON دریافت می‌شود.</p><form method="post"><input type="hidden" name="csrf" value="'.nzc_e($_SESSION['csrf']??'').'"><input type="hidden" name="action" value="request_account_export"><button class="btn primary" style="width:100%">دریافت فایل اطلاعات من</button></form><a class="btn ghost" style="margin-top:12px;width:100%" href="/nz?page=privacy">بازگشت</a></div></main>';
    if($page==='account-delete')return'<main class="page page-narrow"><div class="surface"><h1>حذف حساب</h1><p class="lead">شماره و اطلاعات شناسایی حساب حذف می‌شود، آگهی‌های شما از نمایش عمومی خارج می‌شوند و فقط شناسه‌های ناشناس لازم برای یکپارچگی گفتگوها، امنیت و جلوگیری از سوءاستفاده باقی می‌مانند.</p><form method="post"><input type="hidden" name="csrf" value="'.nzc_e($_SESSION['csrf']??'').'"><input type="hidden" name="action" value="deactivate_account"><div class="field"><label for="nzDeleteConfirm">برای تأیید کلمه «حذف» را بنویسید</label><input id="nzDeleteConfirm" name="confirm" required autocomplete="off"></div><button class="btn danger" style="width:100%">حذف حساب من</button></form><a class="btn ghost" style="margin-top:12px;width:100%" href="/nz?page=privacy">انصراف</a></div></main>';
    return'';
}
function nzlegal_enhance(string $html): string {
    $page=(string)($_GET['page']??'');if(in_array($page,['privacy','rules','safety','about','account-data','account-delete'],true)&&function_exists('nzd_replace_main'))$html=nzd_replace_main($html,nzlegal_page($page));
    if($page==='profile')$html=str_replace('</div><form method="post" style="margin-top:18px">','<a class="menu-item" href="/nz?page=privacy"><span>حریم خصوصی و اطلاعات من</span><span>‹</span></a><a class="menu-item" href="/nz?page=rules"><span>قوانین انتشار</span><span>‹</span></a><a class="menu-item" href="/nz?page=safety"><span>راهنمای معامله امن</span><span>‹</span></a></div><form method="post" style="margin-top:18px">',$html);
    $footer='<footer class="nz-legal-footer" style="max-width:1180px;margin:24px auto 90px;padding:0 16px;text-align:center;color:#70757d;font-size:13px;line-height:2"><a href="/nz?page=about">درباره نیازستان</a> · <a href="/nz?page=rules">قوانین</a> · <a href="/nz?page=privacy">حریم خصوصی</a> · <a href="/nz?page=safety">معامله امن</a> · <a href="/nz?page=support">پشتیبانی</a><div>نیازستان · پلتفرم مستقل خرید، فروش و خدمات</div></footer>';
    if(!str_contains($html,'class="nz-legal-footer"'))$html=str_replace('</body>',$footer.'</body>',$html);return$html;
}